4	/// `WhileSome` is an iterator that yields the `Some` elements of an iterator,
5	/// halting as soon as any `None` is produced.
6	///
7	/// This struct is created by the [`while_some()`] method on [`ParallelIterator`]
8	///
9	/// [`while_some()`]: ParallelIterator::while_some()
10	#[must_use = "iterator adaptors are lazy and do nothing unless consumed"]
11	#[derive(Debug, Clone)]
12	pub struct WhileSome<I> {
13	    base: I,
14	}
15	
16	impl<I> WhileSome<I> {
17	    /// Creates a new `WhileSome` iterator.
18	    pub(super) fn new(base: I) -> Self {
19	        WhileSome { base }
20	    }
21	}
22	
23	impl<I, T> ParallelIterator for WhileSome<I>
24	where
25	    I: ParallelIterator<Item = Option<T>>,
26	    T: Send,
27	{
28	    type Item = T;
29	
30	    fn drive_unindexed<C>(self, consumer: C) -> C::Result
31	    where
32	        C: UnindexedConsumer<Self::Item>,
33	    {
34	        let full = AtomicBool::new(false);
35	        let consumer1 = WhileSomeConsumer {
36	            base: consumer,
37	            full: &full,
38	        };
39	        self.base.drive_unindexed(consumer1)
40	    }
41	}
42	
43	// ////////////////////////////////////////////////////////////////////////
44	// Consumer implementation
45	
46	struct WhileSomeConsumer<'f, C> {
47	    base: C,
48	    full: &'f AtomicBool,
49	}
50	
51	impl<'f, T, C> Consumer<Option<T>> for WhileSomeConsumer<'f, C>
52	where
53	    C: Consumer<T>,
54	    T: Send,
55	{
56	    type Folder = WhileSomeFolder<'f, C::Folder>;
57	    type Reducer = C::Reducer;
58	    type Result = C::Result;
59	
60	    fn split_at(self, index: usize) -> (Self, Self, Self::Reducer) {
61	        let (left, right, reducer) = self.base.split_at(index);
62	        (
63	            WhileSomeConsumer { base: left, ..self },
64	            WhileSomeConsumer {
65	                base: right,
66	                ..self
67	            },
68	            reducer,
69	        )
70	    }
71	
72	    fn into_folder(self) -> Self::Folder {
73	        WhileSomeFolder {
74	            base: self.base.into_folder(),
75	            full: self.full,
76	        }
77	    }
78	
79	    fn full(&self) -> bool {
80	        self.full.load(Ordering::Relaxed) || self.base.full()
81	    }
82	}
83	
84	impl<'f, T, C> UnindexedConsumer<Option<T>> for WhileSomeConsumer<'f, C>
85	where
86	    C: UnindexedConsumer<T>,
87	    T: Send,
88	{
89	    fn split_off_left(&self) -> Self {
90	        WhileSomeConsumer {
91	            base: self.base.split_off_left(),
92	            ..*self
93	        }
94	    }
95	
96	    fn to_reducer(&self) -> Self::Reducer {
97	        self.base.to_reducer()
98	    }
99	}
100	
101	struct WhileSomeFolder<'f, C> {
102	    base: C,
103	    full: &'f AtomicBool,
104	}
105	
106	impl<'f, T, C> Folder<Option<T>> for WhileSomeFolder<'f, C>
107	where
108	    C: Folder<T>,
109	{
110	    type Result = C::Result;
111	
112	    fn consume(mut self, item: Option<T>) -> Self {
113	        match item {
114	            Some(item) => self.base = self.base.consume(item),
115	            None => self.full.store(true, Ordering::Relaxed),
116	        }
117	        self
118	    }
119	
120	    fn consume_iter<I>(mut self, iter: I) -> Self
121	    where
122	        I: IntoIterator<Item = Option<T>>,
123	    {
124	        fn some<T>(full: &AtomicBool) -> impl Fn(&Option<T>) -> bool + '_ {
125	            move |x| match *x {
126	                Some(_) => !full.load(Ordering::Relaxed),
127	                None => {
128	                    full.store(true, Ordering::Relaxed);
129	                    false
130	                }
131	            }
132	        }
133	
134	        self.base = self.base.consume_iter(
135	            iter.into_iter()
136	                .take_while(some(self.full))
137	                .map(Option::unwrap),
138	        );
139	        self
140	    }
141	
142	    fn complete(self) -> C::Result {
143	        self.base.complete()
144	    }
145	
146	    fn full(&self) -> bool {
147	        self.full.load(Ordering::Relaxed) || self.base.full()
148	    }
149	}
